import{a as n}from"./chunk-VJ3SMEKL.js";import{a as e}from"./chunk-2RJSKV3I.js";import"./chunk-U37H3HIF.js";var a=e(n,["매주 찾게 되는 링크, 파일, 메모, 사람들이에요. 여기에는 학생에 관한 내용이 없어요.","추가","파일","링크","이름 추가","메모","사람 추가",{one:"추가했어요.",other:"파일 {n}개를 추가했어요."},"이메일 주소처럼 보이지 않아요.","웹 주소처럼 보이지 않아요. 브라우저 주소창에서 붙여 넣으세요.","취소","여기서는 복사할 수 없었어요.","그 파일을 읽을 수 없어서 추가하지 않았어요.","각 파일의 사본은 작업과 함께 보관돼요. 학교가 온라인에 올려 둔 것이라면 링크가 알아서 최신 상태를 유지해요.","링크 복사","이메일 주소 복사","삭제","“{name}”을(를) 삭제했어요.","내려받기","편집…","{name}에게 이메일","전체","학교 페이지 검색",{one:"항목 {n}개 보관 중.",other:"항목 {n}개 보관 중."},{one:"파일 {n}개 ({size}).",other:"파일 {n}개 ({size})."},"대상: {names}","대상 학급 (선택)","학급용 링크는 1년 내내 그 학급의 모든 수업에 표시돼요.","학교 전체용이면 비워 두세요.","이 브라우저에 그것을 보관할 공간이 없어요.","그룹 (선택)","그룹 {name} 더 보기","고르거나 새로 입력","링크를 복사했어요.","이메일 (선택)","이메일 주소를 복사했어요.","{name} 더 보기","아래로 이동","위로 이동",{one:"할 일 {n}개",other:"할 일 {n}개"},"이름","먼저 이름을 쓰세요.","먼저 메모를 쓰세요.","그룹 “{name}”의 새 이름","“{q}”와 일치하는 항목이 없어요.","역할 없음","여기 있는 모든 것은 다른 작업과 함께 이 컴퓨터에 저장돼요. 이 페이지 아무 곳에나 파일을 끌어다 놓거나 웹 주소를 붙여 넣으세요.","교직원 안내서, 학사 일정, 시정표, 로그인하는 포털, 양식, 무슨 일은 누구에게 연락하는지. 학교가 온라인에 올려 둔 것은 링크로, 파일만 있는 것은 파일로, 또는 직접 쓴 짧은 메모로 추가하세요.","자꾸 찾아보는 것을 한곳에 모아 두세요","아직 이 컴퓨터에 없음","“{name}”은(는) 아직 이 컴퓨터에 없어요. 폴더를 연결하거나 메뉴에서 ‘파일 바꾸기’를 사용하세요.","메모","메모 (선택)","교실 번호, 내선 번호, 이곳에서 일하는 방식","무엇에 쓰는지, 어디를 보면 되는지","기타","사람","아직 자리가 없어요. 사람을 추가하거나, 자리를 바꿔 학교의 역할을 나열하세요.","선택 사항이에요. 함께 일하는 사람만 채우세요. 할 일에 이름을 넣을 수 있고, 이메일 버튼으로 메시지를 바로 쓸 수 있어요.","“{name}”을(를) 삭제했어요. 이 사람 이름이 들어간 할 일은 내용이 그대로 남아요.","이름","평소 쓰는 대로, 예: 김 선생님","교실, 내선 번호, 무엇을 물어보면 되는지","{name} 맨 위에 고정","맨 위에 고정","이름 바꾸기","그룹 이름 바꾸기…","파일 바꾸기…","바꿨어요.","역할","고르거나 학교에서 쓰는 이름 입력","저장","보기","자리 바꾸기…","한 줄에 역할 하나씩, 보여 줄 순서대로","MYP 코디네이터나 학년 부장처럼 학교에서 쓰는 말을 사용하세요. 이미 채운 사람은 역할이 목록에 없어도 자리를 유지해요. 비워 두면 일반적인 역할을 써요.","사람 자리","“{name}” 편집",{one:"파일 추가",other:"파일 {n}개 추가"},"링크 추가","메모 추가","이 사람의 할 일 추가",{one:"{size}보다 큰 파일 1개는 추가되지 않았어요. 그렇게 큰 파일은 학교가 보관하는 곳의 링크를 추가하세요.",other:"{size}보다 큰 파일 {n}개는 추가되지 않았어요. 그렇게 큰 파일은 학교가 보관하는 곳의 링크를 추가하세요."},"학교에 추가함","학교 항목 삭제함","학교 항목 바뀜","그룹 바뀜","사람 정보 바뀜","맨 위에 고정함","자리 바뀜","{name} 고정 해제","웹 주소","브라우저 주소창에서 붙여 넣으세요"],null);export{a as default};
